//! Differential test against the TS engine.
//!
//! `tests/data/differential.json` holds formulas generated by
//! `tests/data/generate-differential.mjs` (every function with sampled
//! arguments, every operator with sampled operands, tricky date strings...)
//! with what the TS engine returned for each: value and error, against a row
//! and against an empty row, static type, builder type, decimal places, field
//! and lookup references. Runtime helpers are compared the same way.
//!
//! Set `ST_FORMULA_CORPUS` to a larger corpus made by the same script to run
//! it instead.

use std::collections::HashMap;
use std::fmt::Write as _;
use std::path::PathBuf;

use st_formula::{
    FieldDecimalPlaces, FieldNullables, FieldReference, FieldTypes, FixedEnvironment, Object,
    Value, evaluate_formula, extract_field_references, extract_lookup_references,
    infer_formula_type, infer_number_decimal_places, runtime, validate_formula_type,
};

fn corpus_path() -> PathBuf {
    std::env::var_os("ST_FORMULA_CORPUS")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/data/differential.json")
        })
}

/// Undoes the generator's encoding of what JSON cannot hold: `NaN`,
/// infinities, `-0` and `undefined` (read as null, as the engine does).
fn decode(value: &Value) -> Value {
    match value {
        Value::Object(object) if object.len() == 1 => {
            if let Some(Value::Text(number)) = object.get("$number") {
                return Value::Number(match number.as_str() {
                    "NaN" => f64::NAN,
                    "Infinity" => f64::INFINITY,
                    "-Infinity" => f64::NEG_INFINITY,
                    _ => -0.0,
                });
            }
            if object.contains_key("$undefined") || object.contains_key("$function") {
                return Value::Null;
            }
            Value::Object(
                object
                    .iter()
                    .map(|(key, value)| (key, decode(value)))
                    .collect(),
            )
        }
        Value::Object(object) => Value::Object(
            object
                .iter()
                .map(|(key, value)| (key, decode(value)))
                .collect(),
        ),
        Value::Array(items) => Value::Array(items.iter().map(decode).collect()),
        other => other.clone(),
    }
}

#[derive(PartialEq)]
enum Match {
    Exact,
    /// Numbers that differ in the last bits: the transcendental functions of
    /// V8 and of Rust's libm may round differently.
    Ulp,
    Different,
}

fn compare(actual: &Value, expected: &Value) -> Match {
    match (actual, expected) {
        (Value::Number(actual), Value::Number(expected)) => {
            if actual.to_bits() == expected.to_bits() || (actual.is_nan() && expected.is_nan()) {
                Match::Exact
            } else if actual == expected {
                // 0 and -0: JSON writes both as 0.
                Match::Ulp
            } else if (actual - expected).abs() <= expected.abs().max(actual.abs()) * 1e-12 {
                Match::Ulp
            } else {
                Match::Different
            }
        }
        (Value::Array(actual), Value::Array(expected)) if actual.len() == expected.len() => worst(
            actual
                .iter()
                .zip(expected)
                .map(|(actual, expected)| compare(actual, expected)),
        ),
        (Value::Object(actual), Value::Object(expected)) if actual.len() == expected.len() => {
            if !actual.keys().eq(expected.keys()) {
                return Match::Different;
            }
            worst(
                actual
                    .values()
                    .zip(expected.values())
                    .map(|(actual, expected)| compare(actual, expected)),
            )
        }
        (actual, expected) if actual == expected => Match::Exact,
        _ => Match::Different,
    }
}

fn worst(matches: impl Iterator<Item = Match>) -> Match {
    let mut result = Match::Exact;
    for item in matches {
        match item {
            Match::Different => return Match::Different,
            Match::Ulp => result = Match::Ulp,
            Match::Exact => {}
        }
    }
    result
}

fn text(value: Option<&Value>) -> Option<String> {
    value.and_then(Value::as_str).map(str::to_owned)
}

fn object<'a>(value: &'a Value, key: &str) -> &'a Object {
    value
        .as_object()
        .and_then(|object| object.get(key))
        .and_then(Value::as_object)
        .unwrap_or_else(|| panic!("missing {key}"))
}

#[derive(Default)]
struct Report {
    checked: usize,
    ulp: usize,
    ulp_examples: String,
    failures: HashMap<&'static str, (usize, String)>,
}

impl Report {
    fn record(&mut self, category: &'static str, outcome: Match, detail: impl FnOnce() -> String) {
        self.checked += 1;
        match outcome {
            Match::Exact => {}
            Match::Ulp => {
                self.ulp += 1;
                if self.ulp <= 6 {
                    let _ = writeln!(self.ulp_examples, "    {category}: {}", detail());
                }
            }
            Match::Different => {
                let entry = self.failures.entry(category).or_default();
                entry.0 += 1;
                if entry.0 <= 8 {
                    let _ = writeln!(entry.1, "    {}", detail());
                }
            }
        }
    }
}

/// A type result in the corpus's compact form,
/// `[formula_type, array_formula_type, error, nullable]`.
fn type_value(inferred: &st_formula::InferredFormulaType) -> Value {
    Value::Array(vec![
        Value::from(inferred.formula_type.as_str()),
        Value::from(inferred.array_formula_type.clone()),
        Value::from(inferred.error.clone()),
        Value::Bool(inferred.nullable),
    ])
}

/// Formulas whose TS result depends on JavaScript object identity: `switch`
/// compares with `==`, which is true for two references to the same array.
/// Rust values have no identity, so two arrays are never `==` (as two
/// distinct JavaScript arrays are not).
fn is_known_difference(formula: &str) -> bool {
    let Some(rest) = formula.strip_prefix("switch(") else {
        return false;
    };
    let Some((first, rest)) = rest.split_once(", ") else {
        return false;
    };
    first.starts_with("field(") && rest.starts_with(first)
}

fn references_value(references: Result<Vec<FieldReference>, st_formula::Error>) -> Value {
    match references {
        Ok(references) => Value::Array(
            references
                .into_iter()
                .map(|reference| {
                    let mut object = Object::new();
                    match reference {
                        FieldReference::Name(name) => {
                            object.insert("kind", "name");
                            object.insert("value", name);
                        }
                        FieldReference::Id(id) => {
                            object.insert("kind", "id");
                            object.insert("value", id);
                        }
                    }
                    Value::Object(object)
                })
                .collect(),
        ),
        Err(error) => Value::Object([("$error", error.to_string())].into_iter().collect()),
    }
}

#[test]
fn matches_the_ts_engine() {
    let path = corpus_path();
    let text_corpus = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("{}: {error}", path.display()));
    // `Value::parse_json` rather than `serde_json`: numbers must be exact.
    let corpus = Value::parse_json(&text_corpus)
        .unwrap_or_else(|| panic!("{}: invalid JSON", path.display()));
    let root = corpus.as_object().expect("corpus object");
    let Value::Object(context) = decode(root.get("context").expect("context")) else {
        panic!("context")
    };
    let field_types: FieldTypes = object(&corpus, "field_types")
        .iter()
        .filter_map(|(key, value)| Some((key.to_owned(), value.as_str()?.to_owned())))
        .collect();
    let field_nullables: FieldNullables = object(&corpus, "field_nullables")
        .iter()
        .filter_map(|(key, value)| Some((key.to_owned(), value.as_bool()?)))
        .collect();
    let decimal_places: FieldDecimalPlaces = object(&corpus, "decimal_places")
        .iter()
        .filter_map(|(key, value)| Some((key.to_owned(), value.as_f64()? as u32)))
        .collect();
    let empty = Object::new();
    let mut env = FixedEnvironment::new(1_794_052_800_000.0, 7);
    let mut report = Report::default();

    for case in root.get("cases").and_then(Value::as_array).expect("cases") {
        let case = case.as_object().expect("case");
        let formula = case
            .get("formula")
            .and_then(Value::as_str)
            .expect("formula");

        if is_known_difference(formula) {
            continue;
        }
        // Left out when equal to the row result.
        let (empty_value_key, empty_error_key) = if case.contains_key("empty_value") {
            ("empty_value", "empty_error")
        } else {
            ("value", "error")
        };
        for (category, fields, value_key, error_key) in [
            ("value", &context, "value", "error"),
            (
                "value on an empty row",
                &empty,
                empty_value_key,
                empty_error_key,
            ),
        ] {
            let expected_value = decode(case.get(value_key).unwrap_or(&Value::Null));
            let expected_error = text(case.get(error_key));
            let result = evaluate_formula(formula, fields, &mut env);
            let outcome = if result.error != expected_error {
                Match::Different
            } else {
                compare(&result.value, &expected_value)
            };
            report.record(category, outcome, || {
                format!("{formula}\n      rust: {:?} {:?}\n      ts:   {expected_value:?} {expected_error:?}", result.value, result.error)
            });
        }

        let lookup_key = if case.contains_key("typed_lookup") {
            "typed_lookup"
        } else {
            "typed"
        };
        for (category, key, lookup) in [
            ("static type", "typed", None),
            ("static type with lookup", lookup_key, Some("number")),
        ] {
            let expected = case.get(key).cloned().unwrap_or_default();
            let actual = type_value(&validate_formula_type(
                formula,
                &field_types,
                lookup,
                &field_nullables,
            ));
            report.record(category, compare(&actual, &expected), || {
                format!("{formula}\n      rust: {actual:?}\n      ts:   {expected:?}")
            });
        }

        let empty_value = decode(case.get(empty_value_key).unwrap_or(&Value::Null));
        let empty_error = text(case.get(empty_error_key));
        let expected = case.get("inferred").cloned().unwrap_or_default();
        let actual = type_value(&infer_formula_type(
            formula,
            &empty_value,
            empty_error.as_deref(),
            &field_types,
            None,
            &mut env,
        ));
        report.record("builder type", compare(&actual, &expected), || {
            format!("{formula}\n      rust: {actual:?}\n      ts:   {expected:?}")
        });

        let expected = case.get("decimal_places").cloned().unwrap_or_default();
        let actual = match infer_number_decimal_places(formula, &decimal_places) {
            Ok(places) => Value::from(places),
            Err(error) => Value::Object([("$error", error.to_string())].into_iter().collect()),
        };
        report.record("decimal places", compare(&actual, &expected), || {
            format!("{formula}\n      rust: {actual:?}\n      ts:   {expected:?}")
        });

        let expected = case
            .get("references")
            .cloned()
            .unwrap_or_else(|| Value::Array(Vec::new()));
        let actual = references_value(extract_field_references(formula));
        report.record("field references", compare(&actual, &expected), || {
            format!("{formula}\n      rust: {actual:?}\n      ts:   {expected:?}")
        });

        let expected = case
            .get("lookups")
            .cloned()
            .unwrap_or_else(|| Value::Array(Vec::new()));
        let actual = Value::Array(
            extract_lookup_references(formula)
                .into_iter()
                .map(|reference| {
                    Value::Object(
                        [
                            ("throughFieldName", reference.through_field_name),
                            ("targetFieldName", reference.target_field_name),
                        ]
                        .into_iter()
                        .collect(),
                    )
                })
                .collect(),
        );
        report.record("lookup references", compare(&actual, &expected), || {
            format!("{formula}\n      rust: {actual:?}\n      ts:   {expected:?}")
        });
    }

    for call in root
        .get("runtime")
        .and_then(Value::as_array)
        .expect("runtime")
    {
        let call = call.as_object().expect("runtime call");
        let name = call.get("name").and_then(Value::as_str).expect("name");
        let args = match decode(call.get("args").unwrap_or(&Value::Null)) {
            Value::Array(items) => items,
            _ => Vec::new(),
        };
        let expected_error = text(call.get("error"));
        let expected_handled = call.get("handled").and_then(Value::as_bool);
        let expected_value = decode(call.get("value").unwrap_or(&Value::Null));
        let result = runtime::call(name, &args, &mut env);
        let outcome = match (&result, &expected_error, expected_handled) {
            (Err(error), Some(expected), _) if error.message() == expected => Match::Exact,
            (Ok(None), None, Some(false)) => Match::Exact,
            (Ok(Some(value)), None, Some(true)) => compare(value, &expected_value),
            _ => Match::Different,
        };
        report.record("runtime helpers", outcome, || {
            format!("{name}({args:?})\n      rust: {result:?}\n      ts:   {expected_value:?} {expected_error:?} handled={expected_handled:?}")
        });
    }

    let mut summary = format!(
        "{} checks, {} last-bit number differences\n{}",
        report.checked, report.ulp, report.ulp_examples
    );
    let mut categories: Vec<_> = report.failures.iter().collect();
    categories.sort_by_key(|(category, _)| **category);
    for (category, (count, examples)) in &categories {
        let _ = write!(summary, "  {category}: {count} differences\n{examples}");
    }
    eprintln!("{summary}");
    assert!(report.failures.is_empty(), "{summary}");
}
